    /**
     * 获取用户列表
     */
    public function getUserList()
    {
        $params = $this->request->param();
        $page = $params['page'] ?? 1;
        $limit = $params['limit'] ?? 10;
        $keyword = $params['keyword'] ?? '';
        $status = $params['status'] ?? '';
        $role = $params['role'] ?? '';
        $startDate = $params['start_date'] ?? '';
        $endDate = $params['end_date'] ?? '';

        $query = User::where('1=1');

        // 关键词搜索
        if ($keyword) {
            $query->where(function($q) use ($keyword) {
                $q->where('username', 'like', "%{$keyword}%")
                  ->whereOr('nickname', 'like', "%{$keyword}%")
                  ->whereOr('phone', 'like', "%{$keyword}%");
            });
        }

        // 状态筛选
        if ($status !== '') {
            $query->where('status', $status);
        }

        // 角色筛选
        if ($role) {
            $query->where('role', $role);
        }

        // 日期范围筛选
        if ($startDate) {
            $query->where('create_time', '>=', $startDate);
        }
        if ($endDate) {
            $query->where('create_time', '<=', $endDate . ' 23:59:59');
        }

        $total = $query->count();
        $list = $query->order('create_time', 'desc')
            ->page($page, $limit)
            ->select();

        return $this->success([
            'list' => $list,
            'total' => $total,
            'page' => $page,
            'limit' => $limit
        ]);
    }

    /**
     * 获取用户详情
     */
    public function getUserDetail()
    {
        $id = $this->request->param('id');
        if (!$id) {
            return $this->error('用户ID不能为空');
        }

        $user = User::find($id);
        if (!$user) {
            return $this->error('用户不存在');
        }

        return $this->success($user);
    }

    /**
     * 更新用户状态
     */
    public function updateUserStatus()
    {
        $id = $this->request->param('id');
        $status = $this->request->param('status');

        if (!$id) {
            return $this->error('用户ID不能为空');
        }

        $user = User::find($id);
        if (!$user) {
            return $this->error('用户不存在');
        }

        $user->status = $status;
        $user->save();

        return $this->success([], '状态更新成功');
    }

    /**
     * 删除用户
     */
    public function deleteUser()
    {
        $id = $this->request->param('id');
        if (!$id) {
            return $this->error('用户ID不能为空');
        }

        $user = User::find($id);
        if (!$user) {
            return $this->error('用户不存在');
        }

        $user->delete();
        return $this->success([], '删除成功');
    }

    /**
     * 获取用户统计
     */
    public function getUserStats()
    {
        $totalUsers = User::count();
        $activeUsers = User::where('status', 1)->count();
        $todayNewUsers = User::whereTime('create_time', 'today')->count();
        $monthNewUsers = User::whereTime('create_time', 'month')->count();

        return $this->success([
            'total_users' => $totalUsers,
            'active_users' => $activeUsers,
            'today_new_users' => $todayNewUsers,
            'month_new_users' => $monthNewUsers
        ]);
    }

    /**
     * 获取用户增长趋势
     */
    public function getUserGrowth()
    {
        $days = $this->request->param('days', 30);
        $data = [];

        for ($i = $days - 1; $i >= 0; $i--) {
            $date = date('Y-m-d', strtotime("-{$i} days"));
            $count = User::whereTime('create_time', 'between', [$date . ' 00:00:00', $date . ' 23:59:59'])->count();
            $data[] = [
                'date' => $date,
                'count' => $count
            ];
        }

        return $this->success($data);
    }

    /**
     * 获取用户分布
     */
    public function getUserDistribution()
    {
        // 按角色分布
        $roleDistribution = User::field('role, count(*) as count')
            ->group('role')
            ->select();

        // 按状态分布
        $statusDistribution = User::field('status, count(*) as count')
            ->group('status')
            ->select();

        return $this->success([
            'role_distribution' => $roleDistribution,
            'status_distribution' => $statusDistribution
        ]);
    }

    /**
     * 导出用户数据
     */
    public function exportUsers()
    {
        $params = $this->request->param();
        $keyword = $params['keyword'] ?? '';
        $status = $params['status'] ?? '';
        $role = $params['role'] ?? '';

        $query = User::where('1=1');

        if ($keyword) {
            $query->where(function($q) use ($keyword) {
                $q->where('username', 'like', "%{$keyword}%")
                  ->whereOr('nickname', 'like', "%{$keyword}%")
                  ->whereOr('phone', 'like', "%{$keyword}%");
            });
        }

        if ($status !== '') {
            $query->where('status', $status);
        }

        if ($role) {
            $query->where('role', $role);
        }

        $list = $query->order('create_time', 'desc')->select();

        // 这里应该生成Excel文件并返回下载链接
        // 简化处理，返回数据
        return $this->success([
            'list' => $list,
            'export_time' => date('Y-m-d H:i:s')
        ]);
    }
